<template>
  <main class="login-shell"><section class="login-brand-panel register-brand-panel"><div class="login-brand"><span class="brand-mark"><Check/></span>TaskFlow</div><div class="login-message register-message"><h1>Comece seu próprio fluxo.</h1><p>Crie uma conta pessoal e participe de diferentes organizações sem perder sua identidade.</p></div><div class="flow-animation" aria-hidden="true"><div><FolderKanban/><span><strong>Projeto Website</strong><small>Planejamento</small></span></div><i/><div><Check/><span><strong>Criar protótipo</strong><small>Tarefa organizada</small></span></div><i/><div><UserRound/><span><strong>Marina</strong><small>Responsável</small></span></div><i/><div class="flow-done"><Check/><span><strong>Concluído</strong><small>Entrega finalizada</small></span></div></div></section><section class="login-form-side"><form class="login-card register-card" @submit.prevent="submit"><div class="mobile-login-brand"><span class="brand-mark"><Check/></span>TaskFlow</div><p class="login-kicker">PRIMEIRO ACESSO</p><h2>Criar sua conta</h2><p class="login-intro">Sua conta será independente de qualquer organização.</p><button type="button" class="google-button" @click="error='Google OAuth ainda é uma demonstração visual.'"><b>G</b>Continuar com Google</button><div class="auth-divider"><span>ou</span></div><label>Nome completo<div class="login-input"><UserRound/><input v-model="form.name" required/></div></label><label>E-mail<div class="login-input"><Mail/><input v-model="form.email" type="email" required/></div></label><label>Cargo/função profissional<div class="login-input"><Users/><input v-model="form.job" required/></div></label><div class="register-grid"><label>Senha<div class="login-input"><LockKeyhole/><input v-model="form.password" :type="show?'text':'password'" required/></div></label><label>Confirmar senha<div class="login-input"><LockKeyhole/><input v-model="confirm" :type="show?'text':'password'" required/><button type="button" @click="show=!show"><EyeOff v-if="show"/><Eye v-else/></button></div></label></div><div v-if="error" class="login-error">{{error}}</div><button class="login-submit register-submit">Criar conta <span>→</span></button><p class="signup-copy">Já possui uma conta? <RouterLink to="/login">Voltar para o login</RouterLink></p></form></section></main>
</template>
<script setup lang="ts">
import{reactive,ref}from"vue";import{useRouter,RouterLink}from"vue-router";import{Check,Eye,EyeOff,FolderKanban,LockKeyhole,Mail,UserRound,Users}from"lucide-vue-next";import{useAuthStore}from"../stores/auth";
const auth=useAuthStore(),router=useRouter(),show=ref(false),confirm=ref(""),error=ref(""),form=reactive({name:"",email:"",job:"",password:""});
async function submit(){error.value="";if(form.password.length<8)return error.value="A senha precisa ter pelo menos 8 caracteres.";if(form.password!==confirm.value)return error.value="As senhas não coincidem.";try{await auth.register(form);router.replace("/dashboard")}catch(e){error.value=auth.error||((e as Error).message)}}
</script>
